{"command": "cd /work/workspace/documents && python3 - <<'EOF'
import zlib, re, glob
for f in sorted(glob.glob('*.pdf')):
    data = open(f,'rb').read()
    print('='*20, f, '='*20)
    for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
        try:
            txt = zlib.decompress(m.group(1).strip(b'\r\n'))
        except Exception as e:
            continue
        # extract text show operators
        s = txt.decode('latin-1')
        parts = re.findall(r'\((?:[^()\\]|\\.)*\)', s)
        out = '\n'.join(p[1:-1] for p in parts)
        print(out)
EOF"}
